const xml = $json.data || $json.body || (typeof $json === 'string' ? $json : '') || '';

function stripCdataAndTags(s) {
  return s
    .replace(/^<!\[CDATA\[/, '')
    .replace(/\]\]>$/, '')
    .replace(/<[^>]+>/g, '')
    .trim();
}
function extractTag(tag, block) {
  const re = new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`, 'i');
  const m = block.match(re);
  return m ? stripCdataAndTags(m[1]) : '';
}
function extractLink(block) {
  const attrMatch = block.match(/<link[^>]*\shref="([^"]+)"/i);
  if (attrMatch) return attrMatch[1];
  return extractTag('link', block);
}

const blocks = xml.match(/<item[\s\S]*?<\/item>/gi) || xml.match(/<entry[\s\S]*?<\/entry>/gi) || [];
const items = [];
for (const block of blocks) {
  const title = extractTag('title', block);
  const link = extractLink(block);
  const description = extractTag('description', block) || extractTag('summary', block) || extractTag('content', block);
  if (!title) continue;
  items.push({ json: { title, link, contentSnippet: description } });
}
return items;

