const items = $input.all();
const seen = new Set();
const output = [];
for (const item of items) {
  const j = item.json;
  const title = (j.title || '').toString().trim();
  const link = j.link || j.url || '';
  if (!title || seen.has(link)) continue;
  seen.add(link);
  output.push({
    json: {
      title,
      ingress: (j.ingress || j.contentSnippet || j.content || j.summary || '').toString().slice(0, 500),
      link,
      runLabel: 'Morgonbrief — SE',
      runKey: 'SE'
    }
  });
}
return output;

